/**
 * 予約を付ける。Idempotency-Key 必須。付けられるのは食べ処・宿・移動の予定（取りやめ済みにも付けられる）。同じ予定に有効な予約があれば 409 RECORD_ALREADY_ACTIVE（既存の記録IDを返す）。外部の予約サービスは操作しない。
 */
export const createBooking = async (tripId: string,
    eventCreate: EventCreate, options?: Parameters<typeof httpClient>[1]): Promise<createBookingResponse> => {

    const getHeaders = (h?: NonNullable<RequestInit['headers']>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(h as Iterable<Iterable<string>>, (entry) => Array.from(entry) as [string, string]),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
return httpClient<createBookingResponse>(getCreateBookingUrl(tripId),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
    body: JSON.stringify(eventCreate)
  }
);}



